import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Best fit with a fullness bonus: tight leftover is preferred, and
    already-fuller bins get a small extra bonus to avoid opening new bins."""
    C = float(np.max(bins))  # empty bin is always present -> capacity
    if C <= 0:
        return np.zeros_like(bins, dtype=float)
    leftover = (bins - item) / C          # normalised remaining space after placing
    level = 1.0 - bins / C                # normalised fill level before placing
    # Tight fits (small leftover) score high; fuller bins get a bonus;
    # an exact or near-exact fit gets an extra bonus.
    score = -leftover + 0.3 * level - 0.2 * np.exp(-leftover / 0.05)
    return score
